const kGreen = Color(0xFF2E7D32);
const kDarkGreen = Color(0xFF1B5E20);
const kPaleGreen = Color(0xFFE8F5E9);
const kBg = Color(0xFFF6F8F5);

enum WorkModule { dashboard, sites, customers, orders, employees, time, calendar, reports, materials, machines, tasks }

String title(WorkModule m) => switch (m) {
  WorkModule.dashboard => 'Dashboard', WorkModule.sites => 'Baustellen', WorkModule.customers => 'Kunden', WorkModule.orders => 'Aufträge', WorkModule.employees => 'Mitarbeiter', WorkModule.time => 'Zeiterfassung', WorkModule.calendar => 'Kalender', WorkModule.reports => 'Berichte', WorkModule.materials => 'Material', WorkModule.machines => 'Maschinen', WorkModule.tasks => 'Aufgaben',
};
IconData icon(WorkModule m) => switch (m) {
  WorkModule.dashboard => Icons.dashboard_outlined, WorkModule.sites => Icons.location_on_outlined, WorkModule.customers => Icons.people_outline, WorkModule.orders => Icons.assignment_outlined, WorkModule.employees => Icons.groups_outlined, WorkModule.time => Icons.schedule_outlined, WorkModule.calendar => Icons.calendar_month_outlined, WorkModule.reports => Icons.description_outlined, WorkModule.materials => Icons.inventory_2_outlined, WorkModule.machines => Icons.construction_outlined, WorkModule.tasks => Icons.checklist_outlined,
};

class PincusWorkspace extends StatefulWidget { const PincusWorkspace({super.key}); @override State<PincusWorkspace> createState() => _PincusWorkspaceState(); }
class _PincusWorkspaceState extends State<PincusWorkspace> {
  final db = AppDatabase(); WorkModule module = WorkModule.dashboard;
  @override void dispose() { db.close(); super.dispose(); }
  @override Widget build(BuildContext context) { final mobile = MediaQuery.sizeOf(context).width < 800; return Scaffold(backgroundColor: kBg, appBar: AppBar(backgroundColor: kGreen, foregroundColor: Colors.white, title: Row(children: [const Icon(Icons.park_outlined), const SizedBox(width: 10), Text(title(module), style: const TextStyle(fontWeight: FontWeight.w700))]), actions: [IconButton(onPressed: () {}, icon: const Icon(Icons.notifications_none)), const SizedBox(width: 8)]), body: Row(children: [if (!mobile) WorkSidebar(selected: module, onSelect: (m) => setState(() => module = m)), Expanded(child: _page())]), bottomNavigationBar: mobile ? NavigationBar(selectedIndex: _mobileIndex(module), onDestinationSelected: (i) => setState(() => module = _mobileModule(i)), destinations: const [NavigationDestination(icon: Icon(Icons.dashboard_outlined), label: 'Start'), NavigationDestination(icon: Icon(Icons.location_on_outlined), label: 'Baustellen'), NavigationDestination(icon: Icon(Icons.people_outline), label: 'Kunden'), NavigationDestination(icon: Icon(Icons.schedule_outlined), label: 'Zeit'), NavigationDestination(icon: Icon(Icons.more_horiz), label: 'Mehr')]) : null); }
  Widget _page() => switch (module) { WorkModule.dashboard => DashboardView(db: db, onOpen: (m) => setState(() => module = m)), WorkModule.calendar => CalendarView(db: db), _ => ModuleView(db: db, kind: module) };
