class Editor extends StatefulWidget { final AppDatabase db; final WorkModule kind; final dynamic item; const Editor({super.key, required this.db, required this.kind, this.item}); @override State<Editor> createState() => _EditorState(); }
class _EditorState extends State<Editor> {
  final Map<String, TextEditingController> c = {}; List<dynamic> customers = [], sites = [], employees = []; String? customerId, siteId, employeeName; bool loading = true;
  @override void initState() { super.initState(); _load(); }
  TextEditingController field(String key, [String? value]) => c.putIfAbsent(key, () => TextEditingController(text: value ?? ''));
  Future<void> _load() async { customers = await widget.db.select(widget.db.customers).get(); sites = await widget.db.select(widget.db.sites).get(); employees = await widget.db.select(widget.db.employees).get(); final x = widget.item; if (x != null) { customerId = switch(widget.kind) { WorkModule.sites => x.customerId, WorkModule.orders => x.customerId, _ => null }; siteId = switch(widget.kind) { WorkModule.orders => x.siteId?.toString(), WorkModule.time => x.siteId.toString(), WorkModule.reports => x.siteId?.toString(), WorkModule.tasks => x.siteId?.toString(), _ => null }; employeeName = widget.kind == WorkModule.time ? x.employeeName : null; } if (mounted) setState(() => loading = false); }
  @override void dispose() { for (final x in c.values) x.dispose(); super.dispose(); }
